{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    by_id = {}
    source_nodes = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        required = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(key not in node for key in required):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite numeric data")
        by_id[node_id] = node
        source_nodes.append(node)

    roots = [node for node in source_nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root = roots[0]

    children = {node["id"]: [] for node in source_nodes}
    for node in source_nodes:
        parent = node["parent"]
        if parent is None:
            if node["depth"] != 0:
                raise ValueError("root depth must be zero")
        else:
            if parent not in by_id or parent == node["id"]:
                raise ValueError("invalid parent reference")
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("inconsistent node depth")
            children[parent].append(node["id"])

    required = set(required_symbols)
    represented = {node["symbol"] for node in source_nodes}
    if not required.issubset(represented):
        raise ValueError("required symbol is not represented")

    active = set(by_id)
    symbol_counts = {}
    for node in source_nodes:
        symbol_counts[node["symbol"]] = symbol_counts.get(node["symbol"], 0) + 1

    candidates = sorted(source_nodes, key=lambda node: (-node["depth"], node["id"]))
    removed = []
    for node in candidates:
        node_id = node["id"]
        if node_id == root["id"] or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in active for child_id in children[node_id]):
            continue
        next_count = symbol_counts[node["symbol"]] - 1
        if node["symbol"] in required and next_count == 0:
            continue
        active.remove(node_id)
        symbol_counts[node["symbol"]] = next_count
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(active),
    }"}
